examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchStepper(
        [
            MonarchStepperStep(id: {{steps.0.id}}, label: {{steps.0.label}}),
            MonarchStepperStep(id: {{steps.1.id}}, label: {{steps.1.label}}),
            MonarchStepperStep(id: {{steps.2.id}}, label: {{steps.2.label}}, isOptional: {{steps.2.optional}}),
            MonarchStepperStep(id: {{steps.3.id}}, label: {{steps.3.label}}),
        ],
        current: current,
        furthest: furthest
    ) { _, index in
        current = index
        furthest = max(furthest, index)
    }
    HStack(spacing: MonarchTokens.Space.space2) {
        MonarchButton({{back}}, variant: .secondary) {
            current -= 1
        }
        .disabled(current == 0)
        MonarchButton({{continue}}, variant: .primary) {
            current += 1
            furthest = max(furthest, current)
        }
        .disabled(current == 3)
    }
}

